import { handle } from './register';
import type { MainContext } from '../MainContext';

/** Run ids are UUIDs generated by the renderer or main; reject anything else before a DB lookup. */
const RUN_ID = /^[a-zA-Z0-9_-]{1,120}$/;

/**
 * Read-only listing plus an explicit restore of the files a run modified.
 * Restore is refused while the same session is still running so the agent
 * cannot put a file back in its pre-run state while writing it.
 */
export function register(ctx: MainContext): void {
  handle('files:changes', (_event, runId: unknown) => {
    if (typeof runId !== 'string' || !RUN_ID.test(runId)) throw new Error('运行 ID 无效');
    // The renderer only needs display paths; do not widen its view of the filesystem.
    return (ctx.fileHistory?.list(runId) ?? []).map(({ path: _absolute, ...record }) => record);
  });
  handle('files:restore', async (_event, runId: unknown, sessionId: unknown) => {
    if (typeof runId !== 'string' || !RUN_ID.test(runId)) throw new Error('运行 ID 无效');
    if (sessionId !== undefined && (typeof sessionId !== 'string' || !sessionId || sessionId.length > 200)) throw new Error('会话 ID 无效');
    if (sessionId && ctx.runningTasks.has(sessionId)) throw new Error('任务正在运行，请先停止任务再撤销文件修改');
    if (!ctx.fileHistory) throw new Error('文件历史不可用');
    return ctx.fileHistory.restore(runId);
  });
}
